UPDATE scm_supplier
SET name = #{name}, company_name = #{companyName}, contact_name = #{contactName},
    country_code = #{countryCode}, credit_rating = #{creditRating},
    lead_time_days = #{leadTimeDays}, moq = #{moq}, status = #{status}, updated_at = #{updatedAt}
WHERE supplier_id = #{supplierId} AND tenant_id = #{tenantId}
